"""Simple local report workspace over cached, managed report jobs."""

REPORTS_HTML = r'''
<section class="workspace-view" id="workspace-reports" role="tabpanel" aria-labelledby="workspace-tab-reports" hidden>
  <section class="reports-desk" aria-labelledby="room-reports-title">
    <header class="reports-heading"><div><p class="eyebrow">YOUR NETWORK / THE STORY SO FAR</p><h2 id="room-reports-title" tabindex="-1">Your network report</h2><p>See what happened, what needs attention, and where the picture is incomplete.</p></div><span class="reports-local">Saved on this PC</span></header>
    <div class="reports-toolbar"><button type="button" id="reports-create" class="reports-primary" disabled>Make report now</button><button type="button" id="reports-save" disabled>Save report</button><button type="button" id="reports-print" disabled>Print / save PDF</button><label for="reports-range">Time period<select id="reports-range"><option value="day">Last 24 hours</option><option value="today">Today</option><option value="week">Last 7 days</option><option value="custom">Choose dates</option></select></label></div>
    <div id="reports-custom" class="reports-dates" hidden><label for="reports-start">From · this PC's time<input id="reports-start" type="datetime-local"></label><label for="reports-end">To · this PC's time<input id="reports-end" type="datetime-local"></label></div>
    <p class="reports-feedback" id="reports-status" role="status" aria-live="polite">Checking saved reports…</p>
    <div class="reports-progress" id="reports-progress-panel" hidden><progress id="reports-progress" max="100" value="0" aria-label="Report preparation"></progress><span id="reports-progress-label">Reading retained evidence…</span><button type="button" id="reports-cancel">Cancel</button></div>
    <div class="reports-context"><label for="reports-saved">Saved reports<select id="reports-saved" disabled><option>No reports yet</option></select></label><p id="reports-coverage">Reports read the selected dates across retained evidence. Missing measurements stay unknown.</p></div>
    <section class="reports-empty" id="reports-empty" hidden><p class="eyebrow">READY WHEN YOU ARE</p><h3>A clear picture, in one click.</h3><p>Choose <strong>Make report now</strong>. MEGALODON will gather the evidence and build the charts for you.</p><p>Automatic reports appear here when enabled. Nothing is uploaded.</p></section>
    <iframe id="reports-document" class="reports-document" title="Visual network report" sandbox="allow-same-origin allow-modals" referrerpolicy="no-referrer" hidden></iframe>
    <details class="reports-details" id="reports-findings-panel" hidden><summary>Finding details &amp; evidence references</summary><p id="reports-findings-status" role="status"></p><div class="reports-table-scroll" tabindex="0" role="region" aria-label="Finding details"><table><thead><tr><th scope="col">When</th><th scope="col">Finding</th><th scope="col">Source &amp; evidence</th></tr></thead><tbody id="reports-findings-rows"></tbody></table></div><div class="reports-page"><button type="button" id="reports-findings-previous" disabled>Previous</button><button type="button" id="reports-findings-next" disabled>Next</button></div></details>
    <details class="reports-details" id="reports-automation"><summary>Automatic reports <span id="reports-schedule-label">Checking schedule</span></summary><p>MEGALODON prepares reports while its local service is running, even with this page closed. After downtime it catches up with the latest missed report once.</p><form id="reports-schedule-form"><label class="reports-check"><input id="reports-schedule-enabled" type="checkbox" checked> Make reports automatically</label><label for="reports-frequency">How often<select id="reports-frequency"><option value="daily">Every day</option><option value="weekly">Every week</option></select></label><label id="reports-weekday-label" for="reports-weekday" hidden>Day<select id="reports-weekday"><option value="0">Monday</option><option value="1">Tuesday</option><option value="2">Wednesday</option><option value="3">Thursday</option><option value="4">Friday</option><option value="5">Saturday</option><option value="6">Sunday</option></select></label><label for="reports-time">Time on this PC<input type="time" id="reports-time" value="09:00" required></label><button type="submit" id="reports-schedule-save" disabled>Save schedule</button></form><p id="reports-next" role="status"></p><p>Generated reports share your evidence storage limits. Use Save report to keep a personal copy outside automatic cleanup.</p></details>
    <details class="reports-details" id="reports-advanced"><summary>Advanced exports</summary><p>These files are for further analysis. The visual report above is ready to read, save, or print.</p><div class="reports-page"><button id="reports-json" type="button" disabled>Download report data · JSON</button><button id="reports-csv" type="button" disabled>Download findings · CSV</button></div><!-- REPORT_HOSTED_EXPORT --></details>
  </section>
</section>
'''

REPORTS_CSS = r'''
.reports-desk{--report-line:#365461;max-width:1600px;margin:0 auto;padding:1.2rem 0 2rem}.reports-heading{display:flex;align-items:start;justify-content:space-between;gap:1rem;padding-bottom:1.4rem;border-bottom:1px solid var(--report-line)}.reports-heading h2{font-size:clamp(1.75rem,3vw,2.6rem);letter-spacing:-.035em;margin:.3rem 0 .6rem}.reports-desk p{color:#bdd0d9;font-size:.94rem;line-height:1.65}.reports-local{white-space:nowrap;color:#a6eee2;border:1px solid #3c706d;padding:.5rem .7rem;font-size:.85rem}.reports-toolbar{display:flex;flex-wrap:wrap;align-items:end;gap:.7rem;padding:1.3rem 0 .4rem}.reports-desk button,.reports-desk select,.reports-desk input{min-height:44px;font:inherit;color:#e4f4f4;background:#102b36;border:1px solid #426977;border-radius:5px;padding:.65rem .85rem}.reports-desk button{cursor:pointer}.reports-desk button:disabled{opacity:.5;cursor:default}.reports-desk .reports-primary{background:#a1eee5;color:#092930;border-color:#a1eee5;font-weight:750}.reports-desk label{display:grid;gap:.4rem;font-size:.85rem;color:#bdd0d9}.reports-toolbar>label{margin-left:auto;min-width:190px}.reports-dates{display:flex;flex-wrap:wrap;gap:1rem;padding:1rem 0}.reports-feedback{min-height:1.6em;margin:.5rem 0}.reports-context{display:flex;gap:1.5rem;align-items:end;border-bottom:1px solid var(--report-line);padding:1rem 0 1.2rem;margin-bottom:1rem}.reports-context label{flex:0 1 360px;min-width:0}.reports-context p{margin:0;flex:1;font-size:.875rem}.reports-context select{width:100%}.reports-empty{padding:clamp(2rem,7vw,5rem) 1.4rem;border:1px dashed #3f6973;text-align:center;background:#09202a}.reports-empty h3{font-size:1.8rem;margin:.5rem}.reports-document{width:100%;height:78vh;min-height:640px;border:1px solid var(--report-line);background:#f4f8f8;color-scheme:light}.reports-progress{display:flex;flex-wrap:wrap;gap:1rem;align-items:center;padding:1rem;border-left:3px solid #77e7db;background:#0e2c35}.reports-progress progress{flex:1;min-width:130px;accent-color:#77e7db}.reports-details{border-top:1px solid var(--report-line);padding:.5rem 0;margin-top:1rem}.reports-details>summary{cursor:pointer;font-weight:700;min-height:44px;padding:.75rem 0}.reports-details>summary span{color:#a5cacb;font-weight:400;margin-left:1rem}.reports-desk form{display:flex;flex-wrap:wrap;align-items:end;gap:1rem}.reports-desk .reports-check{display:flex;align-items:center;gap:.7rem;min-height:44px}.reports-check input{min-height:20px;width:20px;accent-color:#8ce8d8}.reports-page{display:flex;flex-wrap:wrap;gap:.7rem}.reports-table-scroll{overflow:auto;margin-bottom:1rem}.reports-table-scroll table{width:100%;border-collapse:collapse;min-width:640px}.reports-table-scroll th,.reports-table-scroll td{text-align:left;vertical-align:top;padding:.8rem;border-bottom:1px solid var(--report-line);font-size:.875rem;overflow-wrap:anywhere}.reports-table-scroll td{max-width:420px}.reports-table-scroll small{display:block;line-height:1.6;color:#bdd0d9}.reports-desk :focus-visible{outline:3px solid #a6f4df;outline-offset:3px}.reports-desk [hidden]{display:none!important}.reports-desk .telemetry-coverage{margin:1rem 0;border:0;border-left:2px solid #355f68;padding:.4rem 1rem;background:transparent}.reports-desk .telemetry-coverage h3{font-size:1rem}@media(max-width:760px){.reports-heading{display:block}.reports-local{display:inline-block;margin-top:.5rem}.reports-toolbar>label{margin-left:0;flex-basis:100%}.reports-context{display:block}.reports-context p{margin-top:.8rem}.reports-document{height:75vh;min-height:520px}.reports-desk form{display:grid;grid-template-columns:1fr 1fr}.reports-desk form>.reports-check{grid-column:1/-1}.reports-desk form>*{min-width:0}.reports-details>summary span{display:block;margin:.4rem 0 0}.reports-heading p{margin-bottom:0}}@media print{.reports-heading,.reports-toolbar,.reports-context,.reports-details,.reports-feedback,.reports-progress{display:none!important}.reports-document{height:auto;min-height:0;border:0}}
'''

REPORTS_JS = r'''
(() => {
  'use strict';
  const el=id=>document.getElementById(id),root=el('workspace-reports');if(!root||typeof window==='undefined'||typeof window.addEventListener!=='function')return;
  const v={payload:null,busy:false,failed:false,timer:null,selected:null,html:null,htmlId:null,renderedId:null,revision:0,findingOffset:0,findingTotal:0,findingsBusy:false,scheduleDirty:false,downloadBusy:false};
  const obj=x=>x&&typeof x==='object'&&!Array.isArray(x),txt=(x,n=1024)=>typeof x==='string'&&x.length<=n&&!/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/.test(x),id=x=>typeof x==='string'&&/^[a-f0-9]{32}$/.test(x),stamp=x=>typeof x==='string'&&x.length<=40&&Number.isFinite(Date.parse(x)),num=x=>Number.isSafeInteger(x)&&x>=0;
  const node=(tag,text='')=>{const n=document.createElement(tag);n.textContent=text;return n;},when=x=>stamp(x)?new Date(x).toLocaleString():'Time unavailable',visible=()=>!document.hidden&&!root.hidden,report=()=>v.payload?.reports.find(r=>r.id===v.selected),active=()=>v.payload?.job?.state==='running';
  function checked(p){if(!obj(p)||p.schema!=='megalodon-reports-v1'||typeof p.available!=='boolean'||p.local_only!==true||!(p.operator_token===null||txt(p.operator_token,256))||!Array.isArray(p.reports)||p.reports.length>200||!p.reports.every(r=>obj(r)&&id(r.id)&&['ready','incomplete','expired'].includes(r.state)&&stamp(r.created_at)&&stamp(r.start)&&stamp(r.end)&&txt(r.title,256)&&obj(r.coverage)&&Array.isArray(r.coverage.gaps)&&r.coverage.gaps.length<=200&&r.coverage.gaps.every(x=>txt(x,2048))&&obj(r.summary))||!obj(p.schedule)||typeof p.schedule.enabled!=='boolean'||!/^([01]\d|2[0-3]):[0-5]\d$/.test(p.schedule.time)||!['daily','weekly'].includes(p.schedule.frequency)||!obj(p.job)||!['idle','running','ready','failed','cancelled'].includes(p.job.state))throw Error('Invalid report status');return p;}
  async function request(path,body=null,format='json',cap=1024*1024){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000),headers={'X-Megalodon-Check':'1'};if(body!==null){headers['Content-Type']='application/json';headers['X-Megalodon-Reports-Token']=v.payload?.operator_token||'';}try{const response=await fetch(path,{method:body===null?'GET':'POST',credentials:'same-origin',cache:'no-store',headers,signal:controller.signal,...(body===null?{}:{body:JSON.stringify(body)})});if(!response.ok)throw Error('Unavailable');if(Number(response.headers.get('content-length'))>cap)throw Error('Too large');let text;if(response.body?.getReader){const reader=response.body.getReader(),parts=[];let size=0;try{while(true){const part=await reader.read();if(part.done)break;size+=part.value.byteLength;if(size>cap)throw Error('Too large');parts.push(part.value);}const bytes=new Uint8Array(size);let at=0;for(const part of parts){bytes.set(part,at);at+=part.length;}text=new TextDecoder('utf-8',{fatal:true}).decode(bytes);}catch(error){await reader.cancel();throw error;}}else{text=await response.text();if(new TextEncoder().encode(text).length>cap)throw Error('Too large');}return format==='text'?text:JSON.parse(text);}finally{clearTimeout(timer);}}
  function controls(){const ready=report()&&report().state!=='expired',enabled=v.payload?.available&&!v.failed;el('reports-create').disabled=!enabled||v.busy||active();el('reports-cancel').disabled=!enabled||v.busy||!active();for(const name of ['save','json','csv'])el('reports-'+name).disabled=!ready||v.downloadBusy;el('reports-print').disabled=!ready||v.htmlId!==v.selected||v.renderedId!==v.selected||v.downloadBusy;el('reports-saved').disabled=!v.payload?.reports.length;el('reports-schedule-save').disabled=!enabled||v.busy;el('reports-findings-previous').disabled=v.findingsBusy||v.findingOffset===0;el('reports-findings-next').disabled=v.findingsBusy||v.findingOffset+50>=v.findingTotal;}
  function render(){const p=v.payload;if(!p)return;const old=v.selected;if(p.job.state==='ready'&&id(p.job.report_id)&&p.job.report_id!==v.lastJobReport){v.selected=p.job.report_id;v.lastJobReport=p.job.report_id;}const ready=p.reports.find(r=>r.state!=='expired');if(!p.reports.some(r=>r.id===v.selected))v.selected=ready?.id||p.reports[0]?.id||null;const select=el('reports-saved');select.replaceChildren(...(p.reports.length?p.reports.map(r=>{const o=node('option',when(r.created_at)+' · '+(r.state==='incomplete'?'Partial coverage':r.state==='expired'?'Expired':'Ready'));o.value=r.id;return o;}):[node('option','No reports yet')]));select.value=v.selected||'';
    const r=report();el('reports-empty').hidden=!p.available||Boolean(r&&r.state!=='expired');el('reports-findings-panel').hidden=!r||r.state==='expired';el('reports-coverage').textContent=r?when(r.start)+' → '+when(r.end)+(r.state==='expired'?' · This report has expired under your storage policy.':r.coverage.partial?' · Partial coverage. Open the report for missing intervals.':' · Retained evidence in this period; sensor completeness is not guaranteed.'):'Reports read the selected dates across retained evidence. Missing measurements stay unknown.';
    el('reports-progress-panel').hidden=!active();const progress=Number(p.job.progress);el('reports-progress').value=Number.isFinite(progress)?Math.max(0,Math.min(100,progress)):0;el('reports-progress-label').textContent=(num(p.job.processed_records)?p.job.processed_records.toLocaleString()+' records reviewed':'Reading retained evidence')+'. Recording continues.';
    if(!v.scheduleDirty){el('reports-schedule-enabled').checked=p.schedule.enabled;el('reports-time').value=p.schedule.time;el('reports-frequency').value=p.schedule.frequency;el('reports-weekday').value=String(p.schedule.weekday??0);}el('reports-weekday-label').hidden=el('reports-frequency').value!=='weekly';el('reports-schedule-label').textContent=p.schedule.enabled?(p.schedule.frequency==='weekly'?'Weekly':'Daily')+' at '+p.schedule.time:'Off';el('reports-next').textContent=(p.schedule.timezone?'Time zone: '+p.schedule.timezone+'. ':'')+(p.schedule.enabled?(stamp(p.schedule.next_at)?'Next report: '+when(p.schedule.next_at):'Next report time will be calculated by the local service.'):'Automatic reports are off.');
    if(!p.available)el('reports-status').textContent='Reports are unavailable until managed evidence is ready. Open Setup → Storage & history.';else if(p.job.state==='failed')el('reports-status').textContent='The latest report could not finish. Your saved reports are preserved. Try Make report now again.';else if(p.job.state==='cancelled')el('reports-status').textContent='Report preparation cancelled. Your saved reports are preserved.';else if(active())el('reports-status').textContent='Making your report. You can keep using the HUD.';else el('reports-status').textContent=r&&r.state!=='expired'?'Your saved report is ready. It will not change when this page refreshes.':'Choose Make report now to create a visual report.';
    if(old!==v.selected){v.revision++;v.findingOffset=0;v.html=null;v.htmlId=null;}if(r&&r.state!=='expired'&&v.htmlId!==r.id)loadDocument();else if(!r||r.state==='expired'){el('reports-document').hidden=true;el('reports-document').removeAttribute('srcdoc');v.htmlId=null;}controls();}
  async function loadDocument(){const selected=v.selected,revision=v.revision;if(!selected||v.loadingId===selected)return;v.loadingId=selected;v.renderedId=null;el('reports-document').hidden=true;el('reports-document').removeAttribute('srcdoc');el('reports-empty').hidden=true;el('reports-status').textContent='Opening saved report…';try{const html=await request('/api/reports/'+selected+'/html',null,'text',16*1024*1024);if(selected!==v.selected||revision!==v.revision)return;if(!/^<!doctype html>/i.test(html.trim())||/<script\b/i.test(html))throw Error('Invalid report document');v.html=html;v.htmlId=selected;v.renderedId=null;el('reports-status').textContent='Your saved report is ready. It will not change when this page refreshes.';el('reports-document').srcdoc=html.replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi,'<link rel="stylesheet" href="/assets/report.css">');el('reports-document').hidden=false;el('reports-empty').hidden=true;if(el('reports-findings-panel').open)loadFindings();}catch(_){if(selected===v.selected){el('reports-status').textContent='This saved report could not be opened. Choose it again to retry; other saved reports are preserved.';el('reports-document').hidden=true;v.htmlId=null;}}finally{if(v.loadingId===selected)v.loadingId=null;controls();}}
  function interval(){const end=new Date(),start=new Date(end),range=el('reports-range').value;if(range==='custom'){const a=new Date(el('reports-start').value),b=new Date(el('reports-end').value);if(!Number.isFinite(+a)||!Number.isFinite(+b)||a>=b||b>end||b-a>30*86400000||a<new Date(+end-30*86400000))throw Error('Choose a start before the end, within the last 30 days, and an end no later than now.');return {start:a.toISOString(),end:b.toISOString()};}if(range==='today')start.setHours(0,0,0,0);else start.setTime(+end-(range==='week'?7:1)*86400000);return {start:start.toISOString(),end:end.toISOString()};}
  async function mutate(action,body){if(v.busy||!v.payload?.available||v.failed)return;v.busy=true;clearTimeout(v.timer);controls();try{await request('/api/reports/'+action,body);if(action==='schedule')v.scheduleDirty=false;v.payload=checked(await request('/api/reports'));v.failed=false;render();if(action==='schedule')el('reports-status').textContent='Automatic report schedule saved on this PC.';}catch(_){el('reports-status').textContent='The request could not be confirmed. Refresh the Reports tab before trying again.';v.failed=true;}finally{v.busy=false;controls();schedule();}}
  async function download(format){if(!report()||report().state==='expired'||v.downloadBusy)return;const selected=v.selected;v.downloadBusy=true;controls();let url;try{const content=format==='html'&&v.htmlId===selected?v.html:await request('/api/reports/'+selected+'/'+format,null,'text',16*1024*1024);url=URL.createObjectURL(new Blob([content],{type:format==='html'?'text/html;charset=utf-8':format==='json'?'application/json':'text/csv;charset=utf-8'}));const link=node('a');link.href=url;link.download='megalodon-report-'+selected+'.'+format;document.body.append(link);link.click();link.remove();el('reports-status').textContent='Report download requested. This personal copy is outside automatic cleanup.';}catch(_){el('reports-status').textContent='The report could not be downloaded. The saved report on this PC is preserved.';}finally{if(url)setTimeout(()=>URL.revokeObjectURL(url),1000);v.downloadBusy=false;controls();}}
  async function loadFindings(){if(v.findingsBusy||!report()||report().state==='expired')return;const selected=v.selected,revision=v.revision;v.findingsBusy=true;controls();try{const p=await request('/api/reports/'+selected+'/findings?offset='+v.findingOffset+'&limit=50');if(selected!==v.selected||revision!==v.revision)return;if(!obj(p)||!num(p.total)||!Array.isArray(p.records)||p.records.length>50||!p.records.every(r=>obj(r)&&txt(r.id,256)&&txt(r.title,8192)&&txt(r.source,512)&&txt(r.severity,40)&&txt(r.evidence_reference,512)))throw Error('Invalid details');v.findingTotal=num(p.retained_details)?p.retained_details:p.total;el('reports-findings-status').textContent=p.records.length?(v.findingOffset+1)+'–'+(v.findingOffset+p.records.length)+' of '+p.total.toLocaleString()+' findings.'+(p.truncated&&num(p.retained_details)&&p.retained_details<p.total?' Detail is limited to '+p.retained_details.toLocaleString()+' retained findings.':''):'No finding details were retained for this report.';el('reports-findings-rows').replaceChildren(...p.records.map(r=>{const row=node('tr'),detail=node('td'),source=node('td');detail.append(node('strong',r.severity+' · '+r.title),node('small',[r.src_ip,r.dst_ip].filter(x=>txt(x,128)).join(' → ')));source.append(node('span',r.source),node('small',r.evidence_reference));row.append(node('td',when(r.observed_at)),detail,source);return row;}));}catch(_){el('reports-findings-status').textContent='Finding details are unavailable. Previously displayed details remain visible.';}finally{v.findingsBusy=false;controls();}}
  function schedule(){clearTimeout(v.timer);if(visible())v.timer=setTimeout(refresh,active()?2000:30000);}
  async function refresh(){if(v.busy||!visible())return;v.busy=true;controls();try{v.payload=checked(await request('/api/reports'));v.failed=false;render();}catch(_){v.failed=true;if(!v.payload)el('reports-schedule-label').textContent='Schedule unavailable';el('reports-status').textContent='Reports could not refresh. Any report already open remains available to save or print.';}finally{v.busy=false;controls();schedule();}}
  el('reports-document').addEventListener('load',()=>{v.renderedId=v.htmlId;controls();});
  el('reports-create').addEventListener('click',()=>{try{mutate('create',interval());}catch(error){el('reports-status').textContent=error.message;}});el('reports-cancel').addEventListener('click',()=>mutate('cancel',{}));el('reports-save').addEventListener('click',()=>download('html'));el('reports-json').addEventListener('click',()=>download('json'));el('reports-csv').addEventListener('click',()=>download('csv'));el('reports-print').addEventListener('click',()=>{if(v.htmlId!==v.selected||v.renderedId!==v.selected)return;try{el('reports-document').contentWindow.focus();el('reports-document').contentWindow.print();el('reports-status').textContent='Print requested. If no print window opens, save the report, open the saved HTML in your browser, and choose Print.';}catch(_){el('reports-status').textContent='Print is unavailable here. Save report, open the saved HTML, and choose Print.';}});
  el('reports-range').addEventListener('change',()=>{el('reports-custom').hidden=el('reports-range').value!=='custom';});el('reports-saved').addEventListener('change',()=>{v.selected=el('reports-saved').value;v.revision++;v.htmlId=null;v.html=null;v.findingOffset=0;v.findingTotal=0;el('reports-findings-rows').replaceChildren();render();});el('reports-findings-panel').addEventListener('toggle',()=>{if(el('reports-findings-panel').open)loadFindings();});el('reports-findings-previous').addEventListener('click',()=>{v.findingOffset=Math.max(0,v.findingOffset-50);loadFindings();});el('reports-findings-next').addEventListener('click',()=>{v.findingOffset+=50;loadFindings();});for(const field of ['enabled','frequency','weekday','time']){const control=el(field==='frequency'?'reports-frequency':field==='weekday'?'reports-weekday':field==='time'?'reports-time':'reports-schedule-enabled');control.addEventListener('change',()=>{v.scheduleDirty=true;el('reports-weekday-label').hidden=el('reports-frequency').value!=='weekly';});}el('reports-schedule-form').addEventListener('submit',event=>{event.preventDefault();mutate('schedule',{enabled:el('reports-schedule-enabled').checked,time:el('reports-time').value,frequency:el('reports-frequency').value,weekday:Number(el('reports-weekday').value)});});
  function sync(){clearTimeout(v.timer);if(visible())refresh();}document.addEventListener('visibilitychange',sync);if(typeof MutationObserver!=='undefined')new MutationObserver(sync).observe(root,{attributes:true,attributeFilter:['hidden']});sync();
})();
'''
